CREATE ALGORITHM=UNDEFINED DEFINER=`hcfi`@`%` SQL SECURITY DEFINER VIEW `cash_balances` AS select `s`.`CashAccount_id` AS `CashAccount_id`,`s`.`CashAccount_Name` AS `CashAccount_Name`,ifnull(`s`.`CashAccount_I`,0) AS `CashAccount_I`,ifnull(`s`.`CashAccount_E`,0) AS `CashAccount_E`,ifnull(`s`.`CashAccount_Net`,0) AS `CashAccount_Net`,`st`.`City_ID` AS `City_ID`,`st`.`City_Name` AS `City_Name`,`st`.`Subproject_ID` AS `Subproject_ID`,`st`.`Subproject_Name` AS `Subproject_Name`,`st`.`Category_Name` AS `Category_Name`,`st`.`Account_ID` AS `Account_ID`,`st`.`Account_Name` AS `Account_Name`,`st`.`Account_Type` AS `Account_Type`,`st`.`tilltype_Name` AS `tilltype_Name`,`st`.`account_IsClosed` AS `account_IsClosed`,ifnull(`act`.`SYR_I`,0) AS `Account_I`,ifnull(`act`.`SYR_E`,0) AS `Account_E`,ifnull((`act`.`SYR_I` - `act`.`SYR_E`),0) AS `Account_Net`,ifnull(`act`.`USD_I`,0) AS `Account_I_USD`,ifnull(`act`.`USD_E`,0) AS `Account_E_USD`,ifnull((`act`.`USD_I` - `act`.`USD_E`),0) AS `Account_Net_USD` from (((select `ca`.`id` AS `CashAccount_id`,`ca`.`Name` AS `CashAccount_Name`,sum((case when (`acttype`.`shortname` = 'I') then `cad`.`amount` else 0 end)) AS `CashAccount_I`,sum((case when (`acttype`.`shortname` = 'E') then `cad`.`amount` else 0 end)) AS `CashAccount_E`,sum((case when (`acttype`.`shortname` = 'I') then `cad`.`amount` when (`acttype`.`shortname` = 'E') then -(`cad`.`amount`) else 0 end)) AS `CashAccount_Net` from (((`cashaccount` `ca` left join `cashaction` `caa` on((`caa`.`cashaccount_id` = `ca`.`id`))) left join `cashaction_denominations` `cad` on((`cad`.`cashaction_id` = `caa`.`id`))) left join `actiontype` `acttype` on((`acttype`.`id` = `cad`.`AType_id`))) group by `ca`.`id`) `s` join (select `ca`.`id` AS `CashAccount_id`,`city`.`ID` AS `City_ID`,`city`.`Name` AS `City_Name`,`sp`.`ID` AS `Subproject_ID`,`sp`.`Name` AS `Subproject_Name`,`cat`.`Name` AS `Category_Name`,`acc`.`ID` AS `Account_ID`,`acc`.`Name` AS `Account_Name`,`atype`.`name` AS `Account_Type`,`tt`.`Name` AS `tilltype_Name`,`acc`.`IsClosed` AS `account_IsClosed` from (((((((((`cashaccount` `ca` left join `cashaccount_subproject` `cas` on((`cas`.`cashaccount_id` = `ca`.`id`))) left join `subproject` `sp` on((`sp`.`ID` = `cas`.`subproject_id`))) left join `account` `acc` on((`acc`.`SubProject_ID` = `sp`.`ID`))) left join `accounttype` `atype` on((`atype`.`id` = `acc`.`Accounttype_id`))) left join `city` on((`city`.`ID` = `sp`.`City_ID`))) left join `project` `p` on((`p`.`ID` = `sp`.`Project_ID`))) left join `category` `cat` on((`cat`.`ID` = `p`.`Category_ID`))) left join `till` on((`till`.`Account_ID` = `acc`.`ID`))) left join `tilltypes` `tt` on((`tt`.`ID` = `till`.`Type_ID`))) where ((lower(`tt`.`Name`) in ('syr','pay')) and (`acc`.`ID` is not null))) `st` on((`st`.`CashAccount_id` = `s`.`CashAccount_id`))) left join (select `a`.`cashaccount_id` AS `cashaccount_id`,`t`.`Account_ID` AS `Account_ID`,sum((case when ((`at`.`shortname` = 'I') and (`tt`.`Name` = 'SYR')) then `a`.`Amount` else 0 end)) AS `SYR_I`,sum((case when ((`at`.`shortname` in ('E','Ex')) and (`tt`.`Name` = 'SYR')) then `a`.`Amount` else 0 end)) AS `SYR_E`,sum((case when ((`at`.`shortname` = 'I') and (`tt`.`Name` = 'USD')) then `a`.`Amount` else 0 end)) AS `USD_I`,sum((case when ((`at`.`shortname` in ('E','Ex')) and (`tt`.`Name` = 'USD')) then `a`.`Amount` else 0 end)) AS `USD_E` from (((`action` `a` join `actiontype` `at` on((`at`.`id` = `a`.`AType_ID`))) join `till` `t` on((`t`.`ID` = `a`.`Till_ID`))) join `tilltypes` `tt` on((`tt`.`ID` = `a`.`currency_tilltype_id`))) group by `a`.`cashaccount_id`,`t`.`Account_ID`) `act` on(((`act`.`cashaccount_id` = `s`.`CashAccount_id`) and (`act`.`Account_ID` = `st`.`Account_ID`)))) group by `s`.`CashAccount_id`,`st`.`Account_ID`
